import{createRouter,createWebHashHistory}from'vue-router';
import{useDemo}from'./stores/demo.js';
import{reporterRoutes}from'./pages/reporter/routes.js';
import{operationsRoutes}from'./pages/operations/routes.js';
import{dataRoutes}from'./pages/data/routes.js';
const Shared=()=>import('./pages/SharedPage.vue'),Management=()=>import('./pages/ManagementPage.vue');
const shared=[['/profile','My account','S04','profile'],['/notifications','Inbox & notifications','S05','notifications'],['/help','Help & workflow','S06','help'],['/forbidden','Access restricted','S07','forbidden']].map(([path,title,screenId,mode])=>({path,component:Shared,meta:{title,screenId,mode}}));
const management=[['/admin/accounts','Account management','M01','users','manage_accounts'],['/admin/roles','Roles & permissions','M02','roles','configure'],['/admin/offices','MARINA offices','M03','offices','configure'],['/admin/reference-data','Reference data','M04','lookups','configure'],['/admin/workflows','Workflow & templates','M05','templates','configure'],['/admin/audit','Audit trail','M06','auditLogs','audit']].map(([path,title,screenId,collection,permission])=>({path,component:Management,meta:{title,screenId,collection,permission}}));
export const routes=[{path:'/',redirect:()=>useDemo().currentUser.value?(useDemo().currentUser.value.role==='reporter'?'/reporter':'/admin'):'/login'},{path:'/login',component:()=>import('./pages/LoginPage.vue'),meta:{authPage:true,title:'Sign in',screenId:'S01'}},{path:'/activate',component:()=>import('./pages/AccountAccessPage.vue'),meta:{authPage:true,title:'Activate issued account',screenId:'S02'}},{path:'/recover',component:()=>import('./pages/AccountAccessPage.vue'),meta:{authPage:true,title:'Recover account',screenId:'S03'}},...shared,...reporterRoutes,...operationsRoutes,...dataRoutes,...management,{path:'/admin/settings',component:()=>import('./pages/SettingsPage.vue'),meta:{title:'System settings',screenId:'M07',permission:'configure'}},{path:'/handoff',component:()=>import('./pages/HandoffPage.vue'),meta:{title:'Developer handoff',screenId:'M08'}},{path:'/:pathMatch(.*)*',redirect:'/forbidden'}];
const router=createRouter({history:createWebHashHistory(),routes,scrollBehavior:()=>({top:0})});
router.beforeEach(to=>{const store=useDemo(),u=store.currentUser.value;if(to.meta.authPage)return true;if(!u)return{path:'/login',query:{redirect:to.fullPath}};if(to.meta.roles?.length){const reporterRoute=to.meta.roles.includes('reporter');if(reporterRoute&&u.role!=='reporter'&&!store.can('admin'))return'/forbidden';if(!reporterRoute&&u.role==='reporter')return'/forbidden';}if(to.meta.permission&&!store.can(to.meta.permission))return'/forbidden';return true;});
export default router;
